import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]

    def ok(skip):
        prev = None
        for i in range(n):
            if i == skip:
                continue
            if prev is not None and a[i] <= prev:
                return False
            prev = a[i]
        return True

    bad = -1
    for i in range(1, n):
        if a[i] <= a[i - 1]:
            bad = i
            break
    if bad == -1:
        print('true')
    else:
        print('true' if ok(bad) or ok(bad - 1) else 'false')

main()

